head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
// 호출메뉴ID를 식별하기 위한 함수사용
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
// 세션정보를 얻기위한 함수사용
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
// 상장관련공통함수
//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
scwin.vScrenID = "ULDSTF05912.xml";
scwin.fr_SecuGrpId = SECUGRP_ID_EW;
scwin.fr_MktId = $c.lc.fn_getMktId(); // 시장구분코드(유가, 코스닥) 전체), 기준은 로그인 사용자의 부서 소속을 기준으로 한다.

scwin.fn_GetPar, scwin.fn_SetPar;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_search = function() {
    var url = "/tradingSuspension.do?method=searchTradingSuspension" + "&DIV_IDX=" + DIV_IDX_LIST_CORP + "&TRS_IDX=" + TRS_IDX_SELECT + "&ISUR_CD=" + cmb_ISUR_CD.BindColVal + "&GUBUN_CD=ELW";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    dts.DataID = encodeURI(url);
    dts.reset();
    $c.cm.ShowWin(grd);
};
scwin.fn_GetParUpdate = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = cmb_ISUR_CD.BindColVal; // 발행기관코드값
    arrPar[1] = cmb_ISUR_CD.getText(); // 발행기관명
    arrPar[2] = scwin.fr_SecuGrpId; // 증권그룹구분	
    arrPar[3] = scwin.fr_MktId; // 시장구분
    arrPar[4] = dts.getCellData(dts.getRowPosition(), "bz_procs_no"); // 업무처리번호
    arrPar[5] = dts.getCellData(dts.getRowPosition(), "HALT_DESNRELS_TP_CD"); // 거래정지지정및해제구분코드
    arrPar[6] = rdo_ISUR_CD.getValue(); // 발행사/기초자산 구분값

    return arrPar.length;
};
scwin.fn_GetParNew = function(arrPar) {
    // 신규생성시 지정하는 평션
    arrPar[0] = cmb_ISUR_CD.BindColVal; // 발행기관코드값
    arrPar[1] = cmb_ISUR_CD.getText(); // 발행기관명
    arrPar[2] = scwin.fr_SecuGrpId; // 증권그룹구분	
    arrPar[3] = scwin.fr_MktId; // 시장구분
    arrPar[4] = ""; // 신규작성시 업무처리번호는 없다.
    arrPar[5] = cmb_RegistTyp.BindColVal; // 거래정지지정및해제구분코드
    arrPar[6] = rdo_ISUR_CD.getValue(); // 발행사/기초자산 구분값

};
scwin.fn_newpre_create_frame = async function(arg, startDd) {
    if (arg == "1" && startDd != "") arg = "3";
    //alert(arg) ;
    /*
    0:지정, 1:해제, 2:지정및해제(유), 3:지정->해제
    */
    switch (arg) {
        case "0":
            await $c.frame.CreateDialogFrame("DLG_TRDSUSP_AGN", "../lstproc/ULDSTF05913.gfm", $c.lc.fn_getSecuGrpNm(scwin.fr_SecuGrpId) + " 매매거래정지 지정", 200, 100, 700, 545, "window");
            break;
        case "2":
            await $c.frame.CreateDialogFrame("DLG_TRDSUSP_ANT", "../lstproc/ULDSTF05915.gfm", $c.lc.fn_getSecuGrpNm(scwin.fr_SecuGrpId) + " 매매거래정지 지정 및 해제", 200, 100, 720, 580, "window");
            break;
        case "3":
            await $c.frame.CreateDialogFrame("DLG_TRDSUSP_TRM", "../lstproc/ULDSTF05932.gfm", $c.lc.fn_getSecuGrpNm(scwin.fr_SecuGrpId) + " 매매거래정지 해제", 200, 100, 685, 690, "window");
            break;
    }

    //fn_search() ; // 다이얼로그 창이 닫히면 조회를 보낸다.
    cmb_RegistTyp.setSelectedIndex(0);
};
scwin.fn_get_isurcode = function() {
    //elw발행사
    dts_ElwInst.DataID = "/CodeAction.do?method=listWrntCd&For=C";
    dts_ElwInst.Reset();
    dts_ElwUly.DataID = "/CodeAction.do?method=listElwUlyCd&For=C";
    dts_ElwUly.Reset();
};
scwin.img_Search_onclick = function() {
    if (cmb_ISUR_CD.getSelectedIndex() == 0) {
        $c.win.alert($c.stf.getMessageParam("MSG-0016", ""));
        cmb_ISUR_CD.focus();
        return;
    }
    scwin.fn_search();
};
scwin.dts_OnLoadError = function() {
    $c.stf.alert_error(dts);
};
scwin.dts_OnLoadCompleted = function(rowcount) {
    txb_TotCnt.setValue("총 " + rowcount + " 건");
    dts.setRowPosition(rowcount, 0);
    $c.cm.CloseWin(rowcount, grd);
};
scwin.img_Close_onclick = function() {
    window.close();
};
scwin.img_Regist_onclick = function() {
    if (cmb_ISUR_CD.getSelectedIndex() == 0) {
        $c.win.alert($c.stf.getMessageParam("MSG-0016", ""));
        cmb_ISUR_CD.focus();
        return true;
    }
    if (cmb_RegistTyp.getSelectedIndex() == 0) {
        $c.win.alert($c.stf.getMessageParam("MSG-0014", ""));
        cmb_RegistTyp.focus();
        return true;
    }
    scwin.fn_GetPar = fn_GetParNew;
    scwin.fn_SetPar = undefined;
    scwin.fn_newpre_create_frame(cmb_RegistTyp.BindColVal, "");
};
scwin.img_Excel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
    if (dts.getTotalRow() > 0) {
        $c.data.downloadGridViewExcel(grd, $c.lc.fn_getSecuGrpNm(scwin.fr_SecuGrpId) + "매매거래정지내역", "", "8");
    } else {
        $c.win.alert(NO_EXCEL_DATA);
    }
};
scwin.grd_OnDblClick = function(row, colid) {
    scwin.fn_GetPar = fn_GetParUpdate; // 수정시 인수를 넘기는 function을 fn_GetPar란 변수에 할당, (팝업화면에서 참조하는 변수명이 fn_GetPar임)
    scwin.fn_SetPar = undefined;

    // 거래정지지정및해제구분코드 값 넘겨야함
    scwin.fn_newpre_create_frame(dts.getCellData(dts.getRowPosition(), "HALT_DESNRELS_TP_CD"), dts.getCellData(dts.getRowPosition(), "TRD_HALT_STRT_DD"));
};
scwin.gform_onload = function() {
    $c.libRoundPanel.PanelToGroupBox(pan_Cnd);
    rdo_ISUR_CD.setValue("1");
    scwin.fn_get_isurcode();
};
scwin.rdo_ISUR_CD_OnSelChange = function() {
    if (rdo_ISUR_CD.getValue() == "1") {
        cmb_ISUR_CD.ComboDataID = "dts_ElwInst";
        cmb_ISUR_CD.setSelectedIndex(0);
    } else if (rdo_ISUR_CD.getValue() == "2") {
        cmb_ISUR_CD.ComboDataID = "dts_ElwUly";
        cmb_ISUR_CD.setSelectedIndex(0);
    }
};
scwin.cmb_ISUR_CD_OnSelChange = function() {
    if (cmb_ISUR_CD.getSelectedIndex() != 0) {
        scwin.fn_search();
    }
};
